import{_ as i,D as r,o as n,c as s,j as o,a as e,I as l,w as a,am as d}from"./chunks/framework.DXw8qDd0.js";const b=JSON.parse('{"title":"Codex任务设计方法论","description":"","frontmatter":{"title":"Codex任务设计方法论","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex任务设计方法论.md","filePath":"笔记/Codex/Codex任务设计方法论.md"}'),c={name:"笔记/Codex/Codex任务设计方法论.md"},p=o("h1",{id:"codex-任务设计方法论",tabindex:"-1"},[e("Codex 任务设计方法论 "),o("a",{class:"header-anchor",href:"#codex-任务设计方法论","aria-label":'Permalink to "Codex 任务设计方法论"'},"​")],-1),h=d('<p>任务设计决定 Codex 的工作质量。一个好的任务会同时说明目标、上下文、范围、约束、验证方式和最终交付。</p><hr><h2 id="任务六要素" tabindex="-1">任务六要素 <a class="header-anchor" href="#任务六要素" aria-label="Permalink to &quot;任务六要素&quot;">​</a></h2><ol><li><strong>目标</strong>：一句话说明结果。示例：修复登录页刷新后状态丢失的问题</li><li><strong>背景</strong>：给出现象和上下文。示例：用户登录后刷新页面，会回到未登录状态</li><li><strong>范围</strong>：限定文件或模块。示例：只修改 src/auth 模块和相关测试</li><li><strong>约束</strong>：写明禁止事项。示例：不改数据库 schema，不引入新依赖</li><li><strong>验证</strong>：给出命令或检查方式。示例：pnpm test auth</li><li><strong>交付</strong>：要求复盘格式。示例：总结根因、改动、测试和风险</li></ol><hr><h2 id="从模糊到清晰" tabindex="-1">从模糊到清晰 <a class="header-anchor" href="#从模糊到清晰" aria-label="Permalink to &quot;从模糊到清晰&quot;">​</a></h2><p><strong>模糊写法</strong>：帮我优化登录逻辑。</p><p><strong>清晰写法</strong>：</p><p>请修复登录页刷新后状态丢失的问题。</p><p>背景：</p><ul><li>用户登录后刷新页面，会回到未登录状态。</li><li>期望刷新后仍能恢复已登录状态。</li></ul><p>范围：</p><ul><li>优先检查 src/auth 和相关测试。</li><li>不改数据库和后端接口。</li></ul><p>验证：</p><ul><li>运行 pnpm test auth。</li><li>如果需要新增测试，请覆盖刷新恢复状态的场景。</li></ul><p>交付：</p><ul><li>说明根因、改动文件、验证结果和剩余风险。</li></ul><hr><h2 id="大任务拆分" tabindex="-1">大任务拆分 <a class="header-anchor" href="#大任务拆分" aria-label="Permalink to &quot;大任务拆分&quot;">​</a></h2><p>大任务建议拆成三步：</p><ol><li><strong>只读分析</strong>：让 Codex 找影响面。</li><li><strong>方案确认</strong>：让 Codex 给出切分和验证方式。</li><li><strong>分步实施</strong>：每次只做一个可验证改动。</li></ol><p><strong>模板</strong>：</p><p>请先不要修改代码。阅读 [模块/目录]，分析 [目标] 会影响哪些文件、接口和测试。请输出：</p><ol><li>影响面</li><li>推荐实施步骤</li><li>每一步的验证方式</li><li>第一阶段最小改动建议</li></ol><hr><h2 id="让-codex-主动暴露不确定性" tabindex="-1">让 Codex 主动暴露不确定性 <a class="header-anchor" href="#让-codex-主动暴露不确定性" aria-label="Permalink to &quot;让 Codex 主动暴露不确定性&quot;">​</a></h2><p>可以在任务末尾加上：</p><p>如果你需要推测，请明确标注&quot;推测&quot;。如果官方文档、代码和测试之间有冲突，请先停下来说明冲突。</p><p>这句话适合文档更新、版本升级、依赖迁移和跨模块改动。</p><hr><h2 id="实践要点" tabindex="-1">实践要点 <a class="header-anchor" href="#实践要点" aria-label="Permalink to &quot;实践要点&quot;">​</a></h2><ul><li>越具体越好。&quot;运行测试：pnpm test&quot; 比&quot;记得测试&quot;有用。</li><li>把生成目录、构建产物、锁文件策略写清楚。</li><li>如果是 monorepo，请说明每个包的边界。</li><li>对安全敏感项目，单独写&quot;禁止事项&quot;。</li></ul><hr>',33);function u(_,x,g,m,C,q){const t=r("VPNolebaseInlineLinkPreview");return n(),s("div",null,[p,o("blockquote",null,[o("p",null,[e("来源：CodexGuide - 任务设计 ("),l(t,{href:"https://codexguide.ai/practice/task-design.html",target:"_blank",rel:"noreferrer"},{default:a(()=>[e("https://codexguide.ai/practice/task-design.html")]),_:1}),e(")")])]),h,o("blockquote",null,[o("p",null,[e("📎 "),l(t,{href:"/ocdsync/笔记/"},{default:a(()=>[e("📒 返回笔记索引")]),_:1})])])])}const k=i(c,[["render",u]]);export{b as __pageData,k as default};
